contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address to, uint256 amount) public {
        require(to != address(0));
        require(to != address(this));

        c.mintToken(address(this), amount); if (__ESBMC_reverted()) return;
        c.freezeAccount(address(this), true); if (__ESBMC_reverted()) return;

        uint256 fromBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 toBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;

        bool reverted;
        c.transfer(to, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint256 fromAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 toAfter = c.balanceOf(to); if (__ESBMC_reverted()) return;

        assert(reverted && fromAfter == fromBefore && toAfter == toBefore);
    }

    receive() external payable {}
}

